select players.first_name, players.last_name from players where players.id in (select p.id from players p join salaries s on p.id = s.player_id join performances perf on p.id = perf.player_id and s.year = perf.year where s.year = 2001 and perf.h > 0 order by (s.salary * 1.0 / perf.h) asc limit 10) and players.id in (select p.id from players p join salaries s on p.id = s.player_id join performances perf on p.id = perf.player_id and s.year = perf.year where s.year = 2001 and perf.rbi > 0 order by (s.salary * 1.0 / perf.rbi) asc limit 10) order by players.id asc;
